const expandedPatterns=[
['strategy','Strategic Plan','STRATEGY','Create a strategic plan for {subject}. Define current state, outcomes, stakeholders, strategic choices, capabilities, dependencies, risks, milestones, metrics and governance.'],
['research','Research Brief','RESEARCH','Develop a reproducible research brief about {subject}. Define questions, scope, search strategy, source hierarchy, evidence table, conflicting findings and confidence. Never invent sources.'],
['requirements','Requirements Specification','REQUIREMENTS','Specify requirements for {subject}. Separate business, user, functional, non-functional and operational requirements. Add IDs, priority, dependencies, acceptance criteria and traceability.'],
['workflow','Operating Workflow','WORKFLOW','Design an end-to-end workflow for {subject}. Map triggers, actors, inputs, decisions, handoffs, systems, exceptions, controls, outputs and escalation.'],
['sop','Standard Operating Procedure','SOP','Write an actionable SOP for {subject}. Include purpose, scope, roles, prerequisites, numbered procedure, safety controls, exceptions, records and quality checks.'],
['risk','Risk Assessment','RISK','Assess risks for {subject}. Build a register with cause, event, consequence, likelihood, impact, controls, residual exposure, owner, mitigation and contingency.'],
['audit','Audit Checklist','AUDIT','Create an evidence-led audit checklist for {subject}. Map control objective, test procedure, evidence, sample approach, pass/fail criteria, severity and remediation. Do not claim certification.'],
['analysis','Performance Analysis','ANALYSIS','Analyze {subject}. Define population, period, metric formulas, data quality, segmentation, baseline, trends, anomalies, confounders and limitations. Do not infer causation from correlation.'],
['roadmap','Implementation Roadmap','ROADMAP','Create a phased roadmap for {subject}. Define outcomes, workstreams, milestones, dependencies, effort ranges, owners, risks, decision gates and success measures.'],
['communication','Communication Plan','COMMUNICATION','Create a stakeholder communication plan for {subject}. Segment audiences, desired behavior, message hierarchy, channels, cadence, feedback loop and escalation.'],
['training','Training Program','TRAINING','Design a training program for {subject}. Define learner profiles, prerequisites, competencies, modules, practice, assessment rubric and measurable outcomes.'],
['evaluation','Evaluation Framework','EVALUATION','Create an evaluation framework for {subject}. Define questions, indicators, baseline, data collection, sampling, ethics, reporting and learning actions.'],
['proposal','Business Proposal','PROPOSAL','Prepare a decision-ready proposal for {subject}. State problem, evidence, options, recommended approach, scope, benefits, cost assumptions, timeline, risks and approval requested.'],
['dashboard','KPI Dashboard Specification','DASHBOARD','Specify a dashboard for {subject}. Define users, decisions, KPI formulas, dimensions, sources, freshness, quality rules, access, alerts and caveats.'],
['customer','Customer Journey Review','CUSTOMER','Review the customer journey for {subject}. Map stages, user goals, touchpoints, friction, accessibility, failure recovery, ownership and experiments.'],
['quality','Quality Plan','QUALITY','Create a quality plan for {subject}. Define standards, objectives, review stages, test methods, sampling, defect severity, evidence, owners and release criteria.'],
['automation','Automation Blueprint','AUTOMATION','Design an automation blueprint for {subject}. Identify tasks, triggers, interfaces, data contracts, permissions, idempotency, retries, observability, approvals and fallback.'],
['architecture','Architecture Review','ARCHITECTURE','Review architecture for {subject}. Describe components, trust boundaries, data flows, dependencies, reliability, security, privacy, observability, failure modes and trade-offs.'],
['policy','Policy Draft','POLICY','Draft an operational policy for {subject}. Define purpose, scope, terms, responsibilities, controls, exceptions, escalation, records and review cadence. Flag legal review needs.'],
['budget','Budget Framework','BUDGET','Build a transparent budget for {subject}. List categories, quantities, unit assumptions, recurring costs, contingencies, scenarios, funding constraints and variance controls. Never invent quotes.'],
['incident','Incident Response Plan','INCIDENT','Create an incident response plan for {subject}. Define severity, detection, triage, containment, communication, evidence, recovery, escalation and post-incident review.'],
['design','Design Brief','DESIGN','Create a design brief for {subject}. Define audience, user needs, constraints, information hierarchy, accessibility, visual direction, deliverables and acceptance criteria.'],
['contract','Contract Operations Review','CONTRACT','Organize review of {subject}. Extract obligations, dates, deliverables, dependencies, renewal and termination from supplied text only. Flag legal interpretation for counsel.'],
['forecast','Forecasting Framework','FORECAST','Build a forecast framework for {subject}. Define horizon, historical data, assumptions, seasonality, scenarios, error metrics, sensitivity and confidence. Label estimates.'],
['launch','Launch Readiness Review','LAUNCH','Assess launch readiness for {subject}. Review scope, ownership, dependencies, support, security, privacy, accessibility, monitoring, rollback and go/no-go criteria.']
] as const
for(const [slug,name] of expandedDomains){if(!localCategories.some(c=>c.slug===slug))localCategories.push({id:localCategories.length+1,slug,name,description:name+' professional command patterns',icon:'command'})}
for(const [domain,name] of expandedDomains){const category=localCategories.find(c=>c.slug===domain)!;for(const [key,label,code,template] of expandedPatterns){const slug=domain+'-'+key;if(localCommands.some(c=>c.slug===slug))continue;localCommands.push({id:localCommands.length+1,slug,name:name+': '+label,syntax:'/'+domain.replace(/-/g,'_').toUpperCase()+'_'+code,description:label+' tailored to '+name.toLowerCase()+'.',instruction_template:'Act as a senior '+name.toLowerCase()+' specialist. '+template+' Execution standard: state the outcome, scope, inputs, assumptions and exclusions; sequence the work into practical steps; explain rationale and trade-offs; provide examples, templates or tables; identify dependencies, edge cases and failure modes; define evidence and measurable acceptance criteria; finish with prioritized next actions. Never fabricate sources, metrics, approvals or completed actions.',example_input:'Prepare a '+label.toLowerCase()+' for a '+name.toLowerCase()+' team.',example_output:'A structured '+label.toLowerCase()+' with scope, steps, evidence, risks and success criteria.',difficulty:['architecture','audit','risk','incident','contract','forecast'].includes(key)?'advanced':'intermediate',status:'reviewed',tags:[domain,key,'cross-industry','professional'],limitations:'Reusable prompt template only. Validate against current evidence, local rules and qualified professional judgment.',category})}}


